import{R as e,e as o,f as r,U as i}from"./chunks/framework.ywem4qy5.js";const h=JSON.parse('{"title":"Import & Export","description":"","frontmatter":{},"headers":[],"relativePath":"forms/import-export.md","filePath":"forms/import-export.md","lastUpdated":1775908585000}'),a={name:"forms/import-export.md"};function n(p,t,m,l,s,f){return o(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="import-export" tabindex="-1">Import &amp; Export <a class="header-anchor" href="#import-export" aria-label="Permalink to &quot;Import &amp; Export&quot;">​</a></h1><p>Form import and export is for moving form definitions, not submission data.</p><p>Use it when you need to move a form between environments, reuse it on another project, or keep a portable copy of the form setup. You can manage both from <code>Formie → Settings → Import/Export</code>.</p><h2 id="exporting-a-form" tabindex="-1">Exporting a form <a class="header-anchor" href="#exporting-a-form" aria-label="Permalink to &quot;Exporting a form&quot;">​</a></h2><p>When you export a form, Formie downloads a JSON file containing the pieces that make up the form itself, including:</p><ul><li>form details</li><li>form settings</li><li>pages and fields</li><li>email notifications</li><li>form template</li><li>email template</li><li>PDF template</li></ul><p>This is a structural export of the form, not a dump of what people have submitted through it.</p><h2 id="importing-a-form" tabindex="-1">Importing a form <a class="header-anchor" href="#importing-a-form" aria-label="Permalink to &quot;Importing a form&quot;">​</a></h2><p>To import a form, upload a JSON file that was previously exported from Formie. Formie will review that file first, then step you through how it should be applied.</p><p>Formie only supports its own export format here. An arbitrary JSON file will not import correctly.</p><p>If Formie finds an existing form with the same handle, you can either:</p><ul><li>create a new form</li><li>update the existing form</li></ul><p>Creating a new form will generate a separate form with a unique handle that you can change later. Updating an existing form is a full overwrite of that form’s structure, including its fields, notifications, and template assignments, so it should be used carefully.</p>',13)])])}const u=e(a,[["render",n]]);export{h as __pageData,u as default};
